export type NavIconKind='home'|'stars'|'grid-search'|'bookmark'|'profile'|keyof typeof Ionicons.glyphMap;
export type FloatingTabItem={key:string;label:string;icon:NavIconKind;active:boolean;onPress:()=>void};
function Sparkle4({size=10,color='#FFFDFA',cutoutBg=colors.orange}:{size?:number;color?:string;cutoutBg?:string}){const r=size*0.62;const half=r/2;return <View style={{width:size,height:size,backgroundColor:color,overflow:'hidden'}}><View style={{position:'absolute',top:-half,left:-half,width:r,height:r,borderRadius:half,backgroundColor:cutoutBg}}/><View style={{position:'absolute',top:-half,right:-half,width:r,height:r,borderRadius:half,backgroundColor:cutoutBg}}/><View style={{position:'absolute',bottom:-half,left:-half,width:r,height:r,borderRadius:half,backgroundColor:cutoutBg}}/><View style={{position:'absolute',bottom:-half,right:-half,width:r,height:r,borderRadius:half,backgroundColor:cutoutBg}}/></View>;}
function NavDuotoneIcon({icon,active}:{icon:NavIconKind;active:boolean}){const softTone=active?'#FFB56B':'rgba(255,238,220,0.55)';const solidTone=active?colors.orange:'#FFFDFA';if(icon==='home'){const houseColor=active?colors.orange:'#FFA652';const starColor='#FFFDFA';return <View style={s.dtCanvas}><View style={[s.dtHouseRoof,{backgroundColor:houseColor}]}/><View style={[s.dtHouseBody,{backgroundColor:houseColor}]}/><View style={s.dtHouseStar}><Sparkle4 size={9.5} color={starColor} cutoutBg={houseColor}/></View></View>;}if(icon==='stars'){return <View style={s.dtCanvas}><Ionicons name="star" size={11.5} color={solidTone} style={s.dtStarLeft}/><Ionicons name="star" size={11.5} color={solidTone} style={s.dtStarRight}/><Ionicons name="star" size={19.5} color={softTone} style={s.dtStarMain}/></View>;}if(icon==='grid-search'){return <View style={s.dtCanvas}><View style={s.dtGridWrap}><View style={[s.dtGridTile,{backgroundColor:softTone}]}/><View style={[s.dtGridTile,{backgroundColor:softTone}]}/><View style={[s.dtGridTile,{backgroundColor:softTone}]}/><View style={s.dtGridSearchSlot}><View style={[s.dtSearchRing,{borderColor:solidTone}]}/><View style={[s.dtSearchHandle,{backgroundColor:solidTone}]}/></View></View></View>;}if(icon==='bookmark'){const boxColor=active?'#FFB56B':'rgba(255,238,220,0.55)';const ribbonColor=active?colors.orange:'#FFFDFA';return <View style={s.dtCanvas}><View style={[s.dtBookBox,{backgroundColor:boxColor}]}><View style={[s.dtBookRibbon,{backgroundColor:ribbonColor}]}><View style={[s.dtBookNotch,{backgroundColor:boxColor}]}/></View></View></View>;}if(icon==='profile'){const hexColor=active?'#FFB56B':'rgba(255,238,220,0.55)';const personColor=active?colors.orange:'#FFFDFA';return <View style={s.dtCanvas}><View style={s.dtHexContainer}><View style={[s.dtHexBar,{backgroundColor:hexColor}]}/><View style={[s.dtHexBar,{backgroundColor:hexColor,transform:[{rotate:'60deg'}]}]}/><View style={[s.dtHexBar,{backgroundColor:hexColor,transform:[{rotate:'-60deg'}]}]}/><View style={[s.dtPersonHead,{backgroundColor:personColor}]}/><View style={[s.dtPersonBust,{backgroundColor:personColor}]}/></View></View>;}return <View style={s.dtCanvas}><View style={[s.dtGenericBadge,{backgroundColor:softTone}]}><Ionicons name={icon as keyof typeof Ionicons.glyphMap} size={18} color={solidTone}/></View></View>;}
function NavTabButton({item,isActive,onSelect}:{item:FloatingTabItem;isActive:boolean;onSelect:()=>void}){const pressScale=React.useRef(new Animated.Value(1)).current;const activeAnim=React.useRef(new Animated.Value(isActive?1:0)).current;React.useEffect(()=>{Animated.spring(activeAnim,{toValue:isActive?1:0,useNativeDriver:true,stiffness:240,damping:16,mass:0.75}).start();},[isActive,activeAnim]);const onPressIn=()=>{Animated.spring(pressScale,{toValue:0.85,useNativeDriver:true,speed:50,bounciness:4}).start();};const onPressOut=()=>{Animated.spring(pressScale,{toValue:1,useNativeDriver:true,stiffness:260,damping:15,mass:0.7}).start();};const iconScale=Animated.multiply(pressScale,activeAnim.interpolate({inputRange:[0,0.5,1],outputRange:[0.96,1.16,1.05]}));const iconTranslateY=activeAnim.interpolate({inputRange:[0,1],outputRange:[0,-1]});return <Pressable accessibilityRole="tab" accessibilityLabel={item.label} accessibilityState={{selected:isActive}} hitSlop={6} onPress={onSelect} onPressIn={onPressIn} onPressOut={onPressOut} style={s.bottomNavItem}><Animated.View style={{transform:[{scale:iconScale},{translateY:iconTranslateY}]}}><NavDuotoneIcon icon={item.icon} active={isActive}/></Animated.View></Pressable>;}
export function FloatingTabBar({items,groupKey='customer'}:{items:FloatingTabItem[];groupKey?:string}){const count=Math.max(items.length,1);const activeIndex=Math.max(0,items.findIndex(x=>x.active));const defaultTrackW=Math.max(260,Dimensions.get('window').width-28-6-10);const [trackW,setTrackW]=useState(defaultTrackW);const slotW=trackW/count;const initialFrom=navMemory[groupKey]??activeIndex;const slideAnim=React.useRef(new Animated.Value(initialFrom)).current;const stretchX=React.useRef(new Animated.Value(1)).current;const stretchY=React.useRef(new Animated.Value(1)).current;const [visualIndex,setVisualIndex]=useState(activeIndex);const animateTo=React.useCallback((targetIndex:number,fromOverride?:number)=>{setVisualIndex(targetIndex);const fromIndex=fromOverride!==undefined?fromOverride:(navMemory[groupKey]??targetIndex);navMemory[groupKey]=targetIndex;if(fromIndex!==targetIndex){slideAnim.setValue(fromIndex);stretchX.setValue(1);stretchY.setValue(1);Animated.parallel([Animated.spring(slideAnim,{toValue:targetIndex,useNativeDriver:true,stiffness:185,damping:19,mass:0.78}),Animated.sequence([Animated.timing(stretchX,{toValue:1.16,duration:120,useNativeDriver:true}),Animated.spring(stretchX,{toValue:1,useNativeDriver:true,stiffness:220,damping:15,mass:0.7})]),Animated.sequence([Animated.timing(stretchY,{toValue:0.92,duration:120,useNativeDriver:true}),Animated.spring(stretchY,{toValue:1,useNativeDriver:true,stiffness:220,damping:15,mass:0.7})])]).start();}else{Animated.spring(slideAnim,{toValue:targetIndex,useNativeDriver:true,stiffness:220,damping:21,mass:0.8}).start();}},[groupKey,slideAnim,stretchX,stretchY]);React.useEffect(()=>{animateTo(activeIndex);},[activeIndex,animateTo]);const handleSelect=(index:number,item:FloatingTabItem)=>{if(index===visualIndex){Animated.sequence([Animated.timing(stretchX,{toValue:1.09,duration:85,useNativeDriver:true}),Animated.spring(stretchX,{toValue:1,useNativeDriver:true,stiffness:260,damping:14})]).start();item.onPress();return;}animateTo(index,visualIndex);item.onPress();};const translateX=slideAnim.interpolate({inputRange:items.map((_,i)=>i),outputRange:items.map((_,i)=>i*slotW)});return <View style={s.bottomNavOuterFrame}><View onLayout={e=>{const w=e.nativeEvent.layout.width-10;if(w>100&&Math.abs(w-trackW)>1)setTrackW(w);}} style={s.bottomNavBar}><View pointerEvents="none" style={s.bottomNavTopSheen}/><View pointerEvents="none" style={s.bottomNavTopRim}/><View pointerEvents="none" style={s.bottomNavBottomShade}/><Animated.View pointerEvents="none" style={[s.bottomNavSlidingPill,{width:Math.max(48,slotW),transform:[{translateX},{scaleX:stretchX},{scaleY:stretchY}]}]}/><View style={s.bottomNavItemsRow}>{items.map((item,idx)=><NavTabButton key={item.key} item={item} isActive={visualIndex===idx} onSelect={()=>handleSelect(idx,item)}/>)}</View></View></View>;}
function useCustomerNavItems(activeKey:string):FloatingTabItem[]{const t=useT();const user=useSession(x=>x.user);return [{key:'home',label:t('Home'),icon:'home',active:activeKey==='home',onPress:()=>router.navigate((user?'/customer/explore':'/discover') as Href)},{key:'favorites',label:t('Saved'),icon:'stars',active:activeKey==='favorites',onPress:()=>router.navigate('/customer/saved' as Href)},{key:'rentals',label:t('Rentals'),icon:'grid-search',active:activeKey==='rentals',onPress:()=>router.navigate('/rentals' as Href)},{key:'trips',label:t('Trips'),icon:'bookmark',active:activeKey==='trips',onPress:()=>router.navigate('/customer/bookings' as Href)},{key:'account',label:t('Account'),icon:'profile',active:activeKey==='account',onPress:()=>router.navigate('/account' as Href)}];}
export function PersistentCustomerBottomNav({pathname}:{pathname:string}){React.useEffect(()=>{persistentCustomerNavMounted=true;return ()=>{persistentCustomerNavMounted=false;};},[]);const clean=pathname.replace(/\/+$/,'')||'/';const activeKey=clean==='/discover'||clean==='/customer/explore'?'home':clean==='/customer/saved'?'favorites':clean==='/rentals'?'rentals':clean==='/customer/bookings'||clean==='/customer/my-trips'?'trips':clean==='/account'?'account':null;const items=useCustomerNavItems(activeKey??'home');if(!activeKey)return null;return <SafeAreaView edges={['bottom']} pointerEvents="box-none" style={s.bottomNavBarWrap}><FloatingTabBar items={items} groupKey="customer"/></SafeAreaView>;}
export function BottomNavigationBar({activeTab='home'}:{activeTab?:'home'|'favorites'|'history'|'settings'|'explore'|'profile'|'rentals'|'account'|'payments'|'trips'}){const active=activeTab==='history'||activeTab==='payments'||activeTab==='trips'?'trips':activeTab==='settings'||activeTab==='profile'||activeTab==='account'?'account':activeTab==='favorites'?'favorites':activeTab==='rentals'||activeTab==='explore'?'rentals':'home';const items=useCustomerNavItems(active);if(persistentCustomerNavMounted)return null;return <SafeAreaView edges={['bottom']} pointerEvents="box-none" style={s.bottomNavBarWrap}><FloatingTabBar items={items} groupKey="customer"/></SafeAreaView>;}
export function Screen({children,title,headerCenter,kicker,refresh,refreshing=false,back=false,rightAction,updatedAt,sticky,bottomNav=false,activeTab='home',hideHeader=false,contentStyle}:{children:ReactNode;title?:string;headerCenter?:ReactNode;kicker?:string;refresh?:()=>void;refreshing?:boolean;back?:boolean;rightAction?:ReactNode;updatedAt?:number;sticky?:ReactNode;bottomNav?:boolean;activeTab?:'home'|'favorites'|'history'|'settings'|'explore'|'profile'|'rentals'|'account'|'payments'|'trips';hideHeader?:boolean;contentStyle?:object}){const t=useT();const net=useNetInfo();return <SafeAreaView style={s.safe} edges={['top','left','right']}>{!hideHeader&&<BrandHeader/>}<KeyboardAvoidingView style={s.flex} behavior={Platform.OS==='ios'?'padding':undefined}><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={[s.content,contentStyle,(bottomNav||!!sticky)&&{paddingBottom:bottomNav&&sticky?220:bottomNav?110:160}]} refreshControl={refresh?<RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.orangeText}/>:undefined}>{(back||rightAction||headerCenter)&&<View style={[s.row,{justifyContent:'space-between',alignItems:'center',marginBottom:4}]}>{back?<Pressable accessibilityRole="button" accessibilityLabel={t('Back')} onPress={()=>router.canGoBack()?router.back():router.replace('/' as Href)} style={s.icon}><Ionicons name="arrow-back" size={20} color={colors.ink}/></Pressable>:<View style={{width:44}}/>}{headerCenter?(typeof headerCenter==='string'?<Text style={[s.cardTitle,{fontSize:18}]}>{t(headerCenter)}</Text>:headerCenter):<View style={{flex:1}}/>}{rightAction?<View>{rightAction}</View>:<View style={{width:44}}/>}</View>}{net.isConnected===false&&<View accessibilityRole="alert" style={s.warning}><Body>{t('Offline — cached information may be out of date.')}</Body></View>}{title&&<ScreenTitle kicker={kicker}>{t(title)}</ScreenTitle>}{children}{updatedAt? <Body muted style={s.meta}>{t('Last updated')}: {date(updatedAt,'en','Africa/Dar_es_Salaam',true)}</Body>:null}</ScrollView>{sticky&&<SafeAreaView edges={bottomNav?[]:['bottom']} style={[s.sticky,bottomNav&&{bottom:68}]}>{sticky}</SafeAreaView>}{bottomNav&&<BottomNavigationBar activeTab={activeTab}/>}</KeyboardAvoidingView></SafeAreaView>;}
export function SectionCard({title,children,dark=false}:{title?:string;children:ReactNode;dark?:boolean}){const t=useT();return <View style={[s.card,dark&&s.dark]}>{title&&<Text accessibilityRole="header" style={[s.cardTitle,dark&&{color:colors.paper}]}>{t(title)}</Text>}{children}</View>;}
export function PrimaryButton({label,onPress,loading=false,disabled=false,testID}:{label:string;onPress:()=>void;loading?:boolean;disabled?:boolean;testID?:string}){const t=useT();const net=useNetInfo();return <Pressable testID={testID} accessibilityRole="button" accessibilityLabel={t(label)} accessibilityState={{disabled:disabled||loading,busy:loading}} onPress={onPress} disabled={disabled||loading} style={({pressed})=>[s.button,(disabled||loading)&&s.disabled,pressed&&{backgroundColor:colors.orangeBright}]}>{loading?<ActivityIndicator color={colors.ink}/>:<Text style={s.buttonText}>{t(label)}</Text>}</Pressable>;}
export function SecondaryButton({label,onPress,disabled=false,loading=false}:{label:string;onPress:()=>void;disabled?:boolean;loading?:boolean}){const t=useT();return <Pressable accessibilityRole="button" accessibilityLabel={t(label)} accessibilityState={{disabled:disabled||loading}} disabled={disabled||loading} onPress={onPress} style={[s.secondary,(disabled||loading)&&s.disabled]}><Text style={s.secondaryText}>{loading?t('Loading…'):t(label)}</Text></Pressable>;}
export function IconButton({label,icon,onPress}:{label:string;icon:string;onPress:()=>void}){return <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress} style={s.icon}><Text style={s.iconText}>{icon}</Text></Pressable>;}
export function StatusChip({status}:{status:string}){const locale=usePreferences(x=>x.locale);return <View style={s.chip}><Text style={s.chipText}>{statusLabel(status,locale)}</Text></View>;}
export function MoneyText({minor,currency='USD',large=false}:{minor:unknown;currency?:string;large?:boolean}){const locale=usePreferences(x=>x.locale);return <Text style={[s.money,large&&{fontSize:28}]}>{amount(minor,currency,locale)}</Text>;}
export function SearchBar({value,onChange,placeholder,onFilterPress,filterActive=false}:{value:string;onChange:(v:string)=>void;placeholder?:string;onFilterPress?:()=>void;filterActive?:boolean}){const t=useT();return <View style={s.searchBarContainer}><Ionicons name="search" size={20} color="#9CA3AF"/><TextInput accessibilityLabel={t('Search experiences')} value={value} onChangeText={onChange} placeholder={placeholder?t(placeholder):t('Search by location or park...')} placeholderTextColor={colors.muted} style={s.searchInput}/>{value.length>0&&<Pressable accessibilityLabel={t('Clear search')} onPress={()=>onChange('')} style={{padding:4}}><Ionicons name="close-circle" size={18} color="#9CA3AF"/></Pressable>}<Pressable accessibilityLabel="Filter" onPress={onFilterPress} style={[s.filterBtn,filterActive&&{backgroundColor:colors.orange,borderColor:colors.orange}]}><Ionicons name="options-outline" size={18} color={filterActive?'#FFFFFF':colors.ink}/></Pressable></View>;}
export function OnboardingHeroBanner({onGetStarted}:{onGetStarted?:()=>void}){const t=useT();return <View style={s.heroBanner}><Image source={images.hero} style={s.heroBannerImage}/><View style={s.heroBannerOverlay}><View style={s.storyDashes}><View style={[s.storyDash,s.storyDashActive]}/><View style={s.storyDash}/><View style={s.storyDash}/></View><Text style={s.heroBannerTitle}>{t('Start Your Next Adventure Today')}</Text><Text style={s.heroBannerSubtitle}>{t('Your perfect getaway is just a tap away. Book with us and create lasting memories!')}</Text>{onGetStarted&&<Pressable style={s.heroBannerBtn} onPress={onGetStarted}><Text style={s.heroBannerBtnText}>{t('Get Started')}</Text></Pressable>}</View></View>;}
export function AnimatedCardPressable({children,onPress,index=0,style,accessibilityLabel}:{children:ReactNode;onPress?:()=>void;index?:number;style?:object;accessibilityLabel?:string}){const scale=React.useRef(new Animated.Value(1)).current;const entrance=React.useRef(new Animated.Value(0)).current;React.useEffect(()=>{Animated.spring(entrance,{toValue:1,delay:Math.min(index*55,280),useNativeDriver:true,stiffness:170,damping:18,mass:0.8}).start();},[entrance,index]);const onPressIn=()=>{Animated.spring(scale,{toValue:0.965,useNativeDriver:true,speed:45,bounciness:4}).start();};const onPressOut=()=>{Animated.spring(scale,{toValue:1,useNativeDriver:true,stiffness:240,damping:15,mass:0.7}).start();};const translateY=entrance.interpolate({inputRange:[0,1],outputRange:[14,0]});return <Animated.View style={[style,{opacity:entrance,transform:[{translateY},{scale}]}]}><Pressable accessibilityRole="button" accessibilityLabel={accessibilityLabel} onPress={onPress} onPressIn={onPressIn} onPressOut={onPressOut} style={{flex:1}}>{children}</Pressable></Animated.View>;}
function AnimatedHeartButton({isFavorite,onPress,dark=false}:{isFavorite:boolean;onPress?:()=>void;dark?:boolean}){const pulse=React.useRef(new Animated.Value(1)).current;const handlePress=()=>{Animated.sequence([Animated.timing(pulse,{toValue:1.34,duration:110,useNativeDriver:true}),Animated.spring(pulse,{toValue:1,useNativeDriver:true,stiffness:260,damping:12})]).start();onPress?.();};return <Pressable accessibilityRole="button" accessibilityLabel="Save" hitSlop={8} onPress={handlePress} style={[s.gridFavorite,dark&&{backgroundColor:'rgba(255,253,250,0.92)'},isFavorite&&{backgroundColor:'#FFF3E6',borderColor:'rgba(255,123,0,0.3)',borderWidth:1}]}><Animated.View style={{transform:[{scale:pulse}]}}><Ionicons name={isFavorite?'heart':'heart-outline'} size={17} color={isFavorite?colors.orange:'#111827'}/></Animated.View></Pressable>;}
export function FeaturedSafariCard({item,index=0,onPress,isFavorite=false,onFavoriteToggle}:{item:RecordData;index?:number;onPress:()=>void;isFavorite?:boolean;onFavoriteToggle?:()=>void}){const slug=str(item.slug).toLowerCase();const source=index===0?images.serengeti:index===1?images.zanzibar:index===2?images.kilimanjaro:index===3?images.elephants:(slug.includes('zanzibar')?images.zanzibar:slug.includes('kilimanjaro')?images.kilimanjaro:slug.includes('tarangire')||slug.includes('elephant')?images.elephants:images.serengeti);const title=str(item.title??item.name,'Serengeti Classic Safari');const locDisplay=str(item.location??item.region??item.destination,'Arusha, Tanzania');const ratingText=str(item.rating,'4.9 (128)');const priceDisplay=str(item.priceDisplay,'TZS 450,000');const durationText=str(item.duration??(item.durationDays?`${item.durationDays} Days`:'7 Days'));const badgeTag=str(item.tag??(slug.includes('zanzibar')?'Island Luxury':slug.includes('kilimanjaro')?'Summit Trek':slug.includes('tarangire')?'Giant Herds':'Big 5 Migration'));return <AnimatedCardPressable index={index} accessibilityLabel={title} onPress={onPress} style={s.featuredCard}><View style={s.featuredCardInner}><Image source={source} style={{position:'absolute',top:0,left:0,right:0,bottom:0}} resizeMode="cover"/><View pointerEvents="none" style={s.featuredShadeTop}/><View pointerEvents="none" style={s.featuredShadeBottom}/><View style={s.featuredTopRow}><View style={s.featuredTopBadges}><View style={s.featuredGlassPill}><Ionicons name="time-outline" size={12} color="#FFFFFF"/><Text style={s.featuredGlassText}>{durationText}</Text></View><View style={[s.featuredGlassPill,{backgroundColor:'rgba(255,123,0,0.88)'}]}><Ionicons name="sparkles" size={11} color="#FFFFFF"/><Text style={s.featuredGlassText}>{badgeTag}</Text></View></View><AnimatedHeartButton isFavorite={isFavorite} onPress={onFavoriteToggle} dark/></View><View style={s.featuredBottomWrap}><View style={{flexDirection:'row',alignItems:'center',gap:6}}><View style={s.featuredRatingPill}><Ionicons name="star" size={11.5} color="#FFB800"/><Text style={s.featuredRatingText}>{ratingText}</Text></View><View style={{flexDirection:'row',alignItems:'center',gap:3}}><Ionicons name="location-sharp" size={12} color="#FFB56B"/><Text style={s.featuredLocText} numberOfLines={1}>{locDisplay}</Text></View></View><Text style={s.featuredTitle} numberOfLines={1}>{title}</Text><View style={s.featuredPriceBar}><View style={{flexDirection:'row',alignItems:'baseline',gap:3}}><Text style={s.featuredPriceLabel}>From </Text><Text style={s.featuredPriceValue}>{priceDisplay}</Text><Text style={s.featuredPriceLabel}>/person</Text></View><View style={s.featuredArrowPill}><Text style={s.featuredArrowText}>Explore</Text><Ionicons name="arrow-forward" size={13} color="#FFFFFF"/></View></View></View></View></AnimatedCardPressable>;}
export function PhotoCard({item,onPress,favorite}:{item:RecordData;onPress:()=>void;favorite?:ReactNode}){const t=useT();const slug=str(item.slug);const source=typeof item.coverUrl==='string'?{uri:item.coverUrl}:slug.includes('zanzibar')?images.zanzibar:slug.includes('kilimanjaro')?images.kilimanjaro:images.safari;const rate=record(item.fromPrice??item.price??rows(item.prices)[0]);const duration=str(item.durationDays??item.duration);const location=str(item.region??item.destination,'Tanzania');return <View style={s.photoCard}><Pressable accessibilityRole="button" accessibilityLabel={str(item.title??item.name)} onPress={onPress}><View style={s.photoWrap}><Image accessibilityLabel={str(item.title??item.name)} source={source} style={s.photo}/>{Boolean(duration)&&<View style={s.durationBadge}><Text style={s.durationBadgeText}>{duration} {t('Days')}</Text></View>}{favorite&&<View style={s.favorite}>{favorite}</View>}</View><View style={s.photoInfo}><View style={[s.row,{justifyContent:'space-between',alignItems:'flex-start'}]}><Text style={[s.cardTitle,{flex:1,paddingRight:8}]}>{str(item.title??item.name)}</Text><View style={s.ratingBadge}><Text style={s.ratingStar}>★</Text><Text style={s.ratingText}>4.9</Text></View></View><View style={[s.row,{gap:4,marginTop:2}]}><Text style={{fontSize:13}}>📍</Text><Body muted style={{fontSize:14}}>{location}</Body></View><View style={[s.row,{justifyContent:'space-between',alignItems:'center',marginTop:6,paddingTop:8,borderTopWidth:1,borderTopColor:colors.line}]}><View style={[s.row,{gap:4,alignItems:'baseline'}]}><Body muted style={{fontSize:13}}>{t('From')}</Body><MoneyText minor={rate.minor??rate.adultAmountMinor??item.fromAmountMinor??item.adultAmountMinor} currency={str(rate.currency??item.currency,'USD')}/></View><Text style={s.exploreLink}>{t('Book Safari')} →</Text></View></View></Pressable></View>;}
export function GridPhotoCard({item,index=0,onPress,favorite,isFavorite=false,onFavoriteToggle}:{item:RecordData;index?:number;onPress:()=>void;favorite?:ReactNode;isFavorite?:boolean;onFavoriteToggle?:()=>void}){const slug=str(item.slug).toLowerCase();const source=index===0?images.serengeti:index===1?images.zanzibar:index===2?images.kilimanjaro:index===3?images.elephants:(slug.includes('zanzibar')?images.zanzibar:slug.includes('kilimanjaro')?images.kilimanjaro:slug.includes('tarangire')||slug.includes('elephant')?images.elephants:images.serengeti);const titles=['Serengeti Safari','Zanzibar Escape','Kilimanjaro Trek','Tarangire Wildlife'];const locs=['Arusha, Tanzania','Zanzibar, Tanzania','Kilimanjaro, Tanzania','Manyara, Tanzania'];const ratings=['4.9 (128)','4.8 (96)','4.9 (214)','4.7 (82)'];const tzsPrices=['TZS 450,000','TZS 280,000','TZS 1,200,000','TZS 520,000'];const daysList=['7 Days','3 Days','6 Days','5 Days'];const perks=['All-Inclusive · 4x4','Beachfront Resort','Private Guide','Luxury Tented Camp'];const title=str(item.title??item.name)||(titles[index%titles.length]??'Serengeti Safari');const locDisplay=str(item.location??item.region??item.destination)||(locs[index%locs.length]??'Arusha, Tanzania');const ratingText=str(item.rating)||(ratings[index%ratings.length]??'4.9 (128)');const priceDisplay=str(item.priceDisplay)||(tzsPrices[index%tzsPrices.length]??'TZS 450,000');const durationText=str(item.duration??(item.durationDays?`${item.durationDays} Days`:''))||(daysList[index%daysList.length]??'7 Days');const perkText=str(item.perk)||(perks[index%perks.length]??'All-Inclusive');return <AnimatedCardPressable index={index} accessibilityLabel={title} onPress={onPress} style={s.gridCard}><View style={s.gridImageWrap}><Image accessibilityLabel={title} source={source} style={s.gridImage} resizeMode="cover"/><View pointerEvents="none" style={s.gridImageBottomScrim}/><View style={s.gridDurationBadge}><Ionicons name="time-outline" size={11} color="#FFFFFF"/><Text style={s.gridDurationText}>{durationText}</Text></View>{favorite?<View style={s.gridFavorite}>{favorite}</View>:<AnimatedHeartButton isFavorite={isFavorite} onPress={onFavoriteToggle}/>}<View style={s.gridImageRatingPill}><Ionicons name="star" size={11} color="#FFB800"/><Text style={s.gridImageRatingScore}>{ratingText.split(' ')[0]}</Text><Text style={s.gridImageRatingCount}>{ratingText.split(' ')[1]}</Text></View></View><View style={s.gridInfo}><View style={s.gridMetaRow}><Ionicons name="location-sharp" size={12} color={colors.orange}/><Text style={s.gridDistanceText} numberOfLines={1}>{locDisplay}</Text></View><Text style={s.gridTitle} numberOfLines={1}>{title}</Text><Text style={s.gridPerkText} numberOfLines={1}>{perkText}</Text><View style={s.gridFooterRow}><View style={s.gridPriceCol}><Text style={s.gridPrice}>{priceDisplay}</Text><Text style={s.gridPriceUnit}>/ person</Text></View><View style={s.gridActionCircle}><Ionicons name="arrow-forward" size={14} color={colors.orange}/></View></View></View></AnimatedCardPressable>;}
export function EmptyState({title='No records yet',message,action}:{title?:string;message?:string;action?:ReactNode}){const t=useT();return <SectionCard><Text style={s.emptyIcon}>◇</Text><Text style={s.cardTitle}>{t(title)}</Text>{message&&<Body muted>{t(message)}</Body>}{action}</SectionCard>;}
export function InlineError({error,retry}:{error:unknown;retry?:()=>void}){const t=useT();const info=errorInfo(error);return <View accessibilityRole="alert" style={s.error}><Text style={s.errorText}>{t(info.message)}</Text>{info.code==='NETWORK_ERROR'&&<Body>{t('Check status before retrying.')}</Body>}{info.requestId&&<Body muted style={s.meta}>{info.requestId}</Body>}{retry&&<SecondaryButton label={info.code==='VERSION_CONFLICT'?'Refresh':'Retry'} onPress={retry}/>}</View>;}
export function Skeleton(){const t=useT();return <View accessibilityLabel={t('Loading…')} style={s.skeleton}><ActivityIndicator color={colors.orangeText}/><Body>{t('Loading…')}</Body></View>;}
export function QueryState({query,children}:{query:{isPending:boolean;error:unknown;data:unknown;refetch:()=>unknown};children:ReactNode}){return query.isPending?<Skeleton/>:query.error?<InlineError error={query.error} retry={()=>void query.refetch()}/>:<>{children}</>;}
export function Chips({items,value,onChange}:{items:{value:string;label:string}[];value:string;onChange:(value:string)=>void}){const t=useT();return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.chips}>{items.map(x=><Pressable key={x.value} accessibilityRole="button" accessibilityState={{selected:value===x.value}} onPress={()=>onChange(x.value)} style={[s.filter,value===x.value&&s.selectedFilter]}><Text style={[s.filterText,value===x.value&&{color:colors.ink}]}>{t(x.label)}</Text></Pressable>)}</ScrollView>;}
export function FormField({label,value,onChange,error,secure=false,multiline=false,keyboard='default',placeholder,onBlur,testID}:{label:string;value:string;onChange:(value:string)=>void;error?:string;secure?:boolean;multiline?:boolean;keyboard?:'default'|'email-address'|'numeric'|'phone-pad';placeholder?:string;onBlur?:()=>void;testID?:string}){const t=useT();return <View style={s.field}><Text style={s.label}>{t(label)}</Text><TextInput testID={testID??label.toLowerCase().replaceAll(' ','-')} accessibilityLabel={t(label)} value={value} onChangeText={onChange} onBlur={onBlur} placeholder={placeholder??t(label)} placeholderTextColor={colors.muted} secureTextEntry={secure} autoCapitalize={keyboard==='email-address'||secure?'none':'sentences'} autoCorrect={!secure&&keyboard==='default'} keyboardType={keyboard} multiline={multiline} style={[s.input,multiline&&{minHeight:110,textAlignVertical:'top'},error&&{borderColor:colors.error}]}/>{Boolean(error)&&<Text accessibilityRole="alert" style={s.errorText}>{t(error??'')}</Text>}</View>;}
export function SelectField({label,value,options,onChange}:{label:string;value:string;options:{label:string;value:string}[];onChange:(value:string)=>void}){const t=useT();const [open,setOpen]=useState(false);return <View style={s.field}><Text style={s.label}>{t(label)}</Text><SecondaryButton label={options.find(x=>x.value===value)?.label??'Select'} onPress={()=>setOpen(true)}/><Modal visible={open} transparent animationType="none" onRequestClose={()=>setOpen(false)}><View style={s.modalShade}><SafeAreaView style={s.modal}><Text style={s.cardTitle}>{t(label)}</Text><ScrollView>{options.map(x=><SecondaryButton key={x.value} label={x.label} onPress={()=>{onChange(x.value);setOpen(false);}}/>)}</ScrollView><SecondaryButton label="Close" onPress={()=>setOpen(false)}/></SafeAreaView></View></Modal></View>;}
export function DateField(props:React.ComponentProps<typeof FormField>){return <FormField {...props} placeholder="YYYY-MM-DD"/>;}
export function TravelerCounter({label,value,min=0,max=20,onChange}:{label:string;value:number;min?:number;max?:number;onChange:(value:number)=>void}){const t=useT();return <View style={[s.row,{justifyContent:'space-between'}]}><Body>{t(label)}</Body><View style={s.row}><IconButton label={`${t(label)} −`} icon="−" onPress={()=>onChange(Math.max(min,value-1))}/><Text accessibilityLabel={`${t(label)} ${value}`} style={s.count}>{value}</Text><IconButton label={`${t(label)} +`} icon="+" onPress={()=>onChange(Math.min(max,value+1))}/></View></View>;}
export function CheckField({label,checked,onChange}:{label:string;checked:boolean;onChange:(value:boolean)=>void}){const t=useT();return <Pressable accessibilityRole="checkbox" accessibilityState={{checked}} accessibilityLabel={t(label)} onPress={()=>onChange(!checked)} style={[s.row,{paddingVertical:10,minHeight:48}]}><Text style={s.checkbox}>{checked?'☑':'☐'}</Text><Body style={s.flex}>{t(label)}</Body></Pressable>;}
export function Timeline({events}:{events:RecordData[]}){return <View>{events.map((e,i)=><View key={str(e.id,String(i))} style={s.timeline}><Text style={s.timelineDot}>●</Text><View style={s.flex}><Text style={s.label}>{str(e.title??e.eventType??e.newStatus??e.type)}</Text><Body>{str(e.body??e.note??e.description)}</Body><Body muted style={s.meta}>{date(e.createdAt??e.at,'en','Africa/Dar_es_Salaam',true)} · {str(record(e.actor).name)}</Body></View></View>)}</View>;}
export function ItineraryAccordion({value}:{value:unknown}){const t=useT();const [open,setOpen]=useState<string|null>(null);const days=Array.isArray(value)?rows(value):rows(record(value).days??record(record(value).content).days);return <View style={s.stack}>{days.map((day,i)=>{const id=str(day.id,String(i));return <SectionCard key={id}><Pressable accessibilityRole="button" accessibilityState={{expanded:open===id}} onPress={()=>setOpen(open===id?null:id)}><Text style={s.cardTitle}>{i+1}. {str(day.title)}</Text><Body muted>{date(day.date)}{str(day.accommodation)}</Body></Pressable>{open===id&&<View style={s.stack}><Body>{str(day.description??day.notes)}</Body>{rows(day.activities).map((activity,j)=><View key={str(activity.id,String(j))}><Text style={s.label}>{str(activity.title??activity.name)}</Text><Body>{str(activity.description??activity.customerText??activity.location)}</Body>{Boolean(activity.guideNotes)&&<Body muted>{str(activity.guideNotes)}</Body>}</View>)}</View>}</SectionCard>;})}{days.length===0&&<Body muted>{t('Awaiting a proposal')}</Body>}</View>;}
export function ConfirmationSheet({visible,title,children,onConfirm,onClose,loading=false}:{visible:boolean;title:string;children?:ReactNode;onConfirm:()=>void;onClose:()=>void;loading?:boolean}){const t=useT();return <Modal transparent visible={visible} animationType="none" onRequestClose={onClose}><View style={s.modalShade}><SafeAreaView style={s.modal}><Text accessibilityRole="header" style={s.title}>{t(title)}</Text>{children}<PrimaryButton label={title} onPress={onConfirm} loading={loading}/><SecondaryButton label="Cancel" onPress={onClose}/></SafeAreaView></View></Modal>;}
export function DocumentRow({document}:{document:RecordData}){const id=str(document.id);return <SectionCard><Text style={s.label}>{str(document.type??document.title)}</Text><StatusChip status={str(document.status)}/><Body muted>{str(document.sourceVersion??document.version)}</Body><SecondaryButton label="Open document" onPress={()=>router.push(`/documents/${id}` as Href)}/></SectionCard>;}
export function PermissionGate({permission,children}:{permission:string;children:ReactNode}){const user=useSession(x=>x.user);return user?.permissions.includes(permission)?<>{children}</>:null;}
export function UnsavedChangesGuard({dirty}:{dirty:boolean}){const t=useT();const navigation=useNavigation();usePreventRemove(dirty,({data})=>{Alert.alert(t('Unsaved changes'),t('Keep editing'),[{text:t('Keep editing'),style:'cancel'},{text:t('Discard'),style:'destructive',onPress:()=>{navigation.dispatch(data.action);}}]);});return null;}
